SELECT N'2.0' AS contract_version,@RunId AS run_id,@SiteLabel AS site,@PeriodStart AS period_start,@PeriodEnd AS period_end,@PeriodReason AS period_reason,@ContextStart AS context_start,@DataThrough AS data_through,@DataThroughConfirmed AS data_through_confirmed,@IncludePseudonymizedDetails AS details_included,N'2.0.0-rc.4' AS collector_release,N'18' AS tested_aria_major,N'NOT_DETECTED_FROM_DWH' AS aria_version_status,1 AS comparison_population_complete,CASE WHEN COL_LENGTH(N'DWH.FactPatientImage',N'DimPatientID') IS NULL OR COL_LENGTH(N'DWH.FactPatientImage',N'DimMachineID') IS NULL OR COL_LENGTH(N'DWH.FactPatientImage',N'ImageCreationDate') IS NULL OR COL_LENGTH(N'DWH.DimPatient',N'DimPatientID') IS NULL OR COL_LENGTH(N'DWH.DimPatient',N'IsMOTestPatient') IS NULL OR COL_LENGTH(N'DWH.DimMachine',N'DimMachineID') IS NULL OR COL_LENGTH(N'DWH.DimMachine',N'MachineId') IS NULL THEN N'UNAVAILABLE' ELSE N'AVAILABLE' END AS image_objects_state,CASE WHEN COL_LENGTH(N'DWH.DimPatient',N'DimPatientID') IS NULL OR COL_LENGTH(N'DWH.DimPatient',N'IsMOTestPatient') IS NULL OR COL_LENGTH(N'DWH.DimMachine',N'DimMachineID') IS NULL OR COL_LENGTH(N'DWH.DimMachine',N'MachineId') IS NULL OR COL_LENGTH(N'DWH.FactTreatmentHistory',N'DimPatientID') IS NULL OR COL_LENGTH(N'DWH.FactTreatmentHistory',N'TreatmentRecordDateTime') IS NULL OR COL_LENGTH(N'DWH.FactTreatmentHistory',N'IsImage') IS NULL OR COL_LENGTH(N'DWH.FactTreatmentHistory',N'IsBrachy') IS NULL OR COL_LENGTH(N'DWH.DimActivityTransaction',N'DimActivityTransactionID') IS NULL OR COL_LENGTH(N'DWH.DimActivityTransaction',N'DimPatientID') IS NULL OR COL_LENGTH(N'DWH.DimActivityTransaction',N'DimActivityID') IS NULL OR COL_LENGTH(N'DWH.DimActivityTransaction',N'AppointmentDateTime') IS NULL OR COL_LENGTH(N'DWH.DimActivityTransaction',N'AppointmentStatus') IS NULL OR COL_LENGTH(N'DWH.DimActivity',N'DimActivityID') IS NULL OR COL_LENGTH(N'DWH.DimActivity',N'ActivityCode') IS NULL OR (COL_LENGTH(N'DWH.FactTreatmentHistory',N'DeliveredMU') IS NULL AND COL_LENGTH(N'DWH.FactTreatmentHistory',N'FieldMUActual') IS NULL AND COL_LENGTH(N'DWH.FactTreatmentHistory',N'DoseDelivered') IS NULL) THEN N'EVENTS_UNAVAILABLE_CHECK_CAPABILITIES' ELSE N'READY' END AS collection_state;